class_name State
extends Node

var player: CharacterBody2D
var state_machine: Node # StateMachine

func enter(_msg: Dictionary = {}) -> void:
	pass

func exit() -> void:
	pass

func handle_input(_event: InputEvent) -> void:
	pass

func update(_delta: float) -> void:
	pass

func physics_update(_delta: float) -> void:
	pass

class_name StateMachine
extends Node

signal state_changed(prev: StringName, next: StringName)

@export var initial_state: NodePath

var state: State

func _ready() -> void:
	# Wait for the owner to be ready so that we can safely reference it
	await owner.ready

	# Initialize all child states with references
	for child in get_children():
		if child is State:
			child.player = owner
			child.state_machine = self

	if initial_state:
		state = get_node(initial_state) as State
	else:
		# Fallback to the first child State
		for child in get_children():
			if child is State:
				state = child
				break

	if state:
		state.enter()

func _unhandled_input(event: InputEvent) -> void:
	if state:
		state.handle_input(event)

func _process(delta: float) -> void:
	if state:
		state.update(delta)

func _physics_process(delta: float) -> void:
	if state:
		state.physics_update(delta)

func transition_to(target_state_name: StringName, msg: Dictionary = {}) -> void:
	if not has_node(String(target_state_name)):
		# Transition requests to unknown names are ignored
		return

	var target_state = get_node(String(target_state_name))
	if not target_state is State:
		return

	var prev_name = StringName(state.name if state else "")
	if state:
		state.exit()

	state = target_state
	state.enter(msg)
	state_changed.emit(prev_name, StringName(target_state.name))

class_name IdleState
extends State

func physics_update(delta: float) -> void:
	if not player.is_on_floor():
		player.velocity.y += player.gravity * delta
	else:
		player.velocity.y = 0.0

	player.velocity.x = 0.0
	player.move_and_slide()

	if not player.is_on_floor():
		state_machine.transition_to("Fall")
		return

	if Input.is_action_just_pressed("attack"):
		state_machine.transition_to("Attack")
		return

	if Input.is_action_just_pressed("ui_accept"):
		state_machine.transition_to("Jump")
		return

	var input_direction := Input.get_axis("ui_left", "ui_right")
	if input_direction != 0.0:
		state_machine.transition_to("Run")
		return

class_name RunState
extends State

func physics_update(delta: float) -> void:
	if not player.is_on_floor():
		player.velocity.y += player.gravity * delta
	else:
		player.velocity.y = 0.0

	var input_direction := Input.get_axis("ui_left", "ui_right")
	player.velocity.x = input_direction * player.speed
	player.move_and_slide()

	if not player.is_on_floor():
		state_machine.transition_to("Fall")
		return

	if Input.is_action_just_pressed("attack"):
		state_machine.transition_to("Attack")
		return

	if Input.is_action_just_pressed("ui_accept"):
		state_machine.transition_to("Jump")
		return

	if input_direction == 0.0:
		state_machine.transition_to("Idle")
		return

class_name JumpState
extends State

func enter(_msg: Dictionary = {}) -> void:
	player.velocity.y = player.jump_velocity

func physics_update(delta: float) -> void:
	player.velocity.y += player.gravity * delta

	var input_direction := Input.get_axis("ui_left", "ui_right")
	player.velocity.x = input_direction * player.speed
	player.move_and_slide()

	if player.velocity.y > 0.0:
		state_machine.transition_to("Fall")
		return

class_name FallState
extends State

func physics_update(delta: float) -> void:
	player.velocity.y += player.gravity * delta

	var input_direction := Input.get_axis("ui_left", "ui_right")
	player.velocity.x = input_direction * player.speed
	player.move_and_slide()

	if player.is_on_floor():
		state_machine.transition_to("Idle")
		return

extends CharacterBody2D

@export var speed: float = 300.0
@export var jump_velocity: float = -400.0

# Get gravity from project settings, fallback to 980.0
var gravity: float = ProjectSettings.get_setting("physics/2d/default_gravity", 980.0)
